import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

// Cross-feature aggregate: a dashboard summarising all three entities. Outstanding total = sum of
// UNPAID invoice amounts across all projects.
test.describe('dashboard', () => {
  test('shows counts and the outstanding total', { tag: '@functionality' }, async ({ page }) => {
    await resetAndSeed({
      clients: [
        { id: 1, name: 'Acme Ltd', email: 'ops@acme.example' },
        { id: 2, name: 'Globex', email: 'ac@globex.example' },
      ],
      projects: [
        { id: 1, name: 'Website Rebuild', clientId: 1 },
        { id: 2, name: 'Intranet', clientId: 2 },
      ],
      invoices: [
        { id: 1, projectId: 1, amount: 100, status: 'UNPAID' },
        { id: 2, projectId: 1, amount: 50, status: 'PAID' },
        { id: 3, projectId: 2, amount: 200, status: 'UNPAID' },
      ],
    });
    await page.goto('/');
    await page.getByTestId('nav-dashboard').click();

    await expect(page.getByTestId('dashboard-clients-count')).toHaveText('2');
    await expect(page.getByTestId('dashboard-projects-count')).toHaveText('2');
    await expect(page.getByTestId('dashboard-outstanding-total')).toHaveText('300.00'); // 100 + 200 unpaid
  });
});
===SEED===
// Shared per-spec data setup (DESIGN.md §9, BASE_CHECKLIST.md §D). Each spec's beforeEach RESETS
// then SEEDS via the app's /__test__ endpoint — this is Arrange, not Assert. Specs still ASSERT
// only through the UI (data-testid).
//
// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
// silent failure would surface later as confusing, misattributed assertion failures on unrelated
// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
// the break is attributed to the seed contract, and so an implementer running its own spec sees the
// broken endpoint immediately instead of shipping it. This helper is fixed test infrastructure — the
// evolving surface is the server-side /__test__ endpoint, not this client.
import { request, type APIResponse } from '@playwright/test';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;

async function must(res: Promise<APIResponse>, what: string): Promise<void> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

// Usage in a spec:
//   test.beforeEach(async () => { await resetAndSeed({ /* rows this spec needs */ }); });
===AUDIT===
import { existsSync, readFileSync } from 'node:fs';

// Read the known audit file — the second test-assertion channel alongside the UI (DESIGN.md §3,
// docs/SUT_CONTRACT.md §4). The app appends one record per line; /__test__/reset clears it per
// spec. Path comes from AUDIT_FILE (set by bin/start / bin/e2e); falls back to the app's default.
const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';

/** All audit records currently in the file, one per element (empty if none). */
export function auditLines(): string[] {
  return existsSync(AUDIT_FILE)
    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
    : [];
}

// Usage in a spec (audit-category test):
//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');
===PWCONFIG===
// Playwright config (BASE_CHECKLIST.md §D). Tests bind to data-testid only and assert through the
// UI only. The app is already running (bin/e2e / the harness start it), so no webServer here.
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './specs', // the harness copies cpNN specs here (dest_subpath: e2e/specs)
  use: {
    baseURL: process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`,
    // Contract attribute is data-testid — Playwright's default, so no testIdAttribute override
    // needed (DESIGN.md §3). Strict awaiting on data-testid presence is the flake guard (§9).
  },
  // Serial + fresh reset+seed per spec (see support/seed.ts) keeps specs isolated. workers:1 is
  // REQUIRED: every spec drives ONE shared app + in-memory H2 through /__test__/reset+seed, so the
  // whole suite must run serially. `fullyParallel:false` alone only serialises tests WITHIN a file
  // — Playwright still runs different spec FILES on parallel workers by default, and those would
  // stomp on each other's seed data (false cross-file failures). One worker = fully serial.
  fullyParallel: false,
  workers: 1,
  reporter: [['list']],
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // Headless Chromium in a restricted/confined environment (e.g. the harness's
        // Landlock-confined agent turn) needs its own sandbox off and shared memory in /tmp,
        // or renderer/GPU child processes crash. Harmless for the unconfined gate run too.
        launchOptions: { args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] },
      },
    },
  ],
});

